// SLA response & resolution time targets (in minutes)
const SLA_POLICY = {
  critical: { first_response_mins: 15, resolution_mins: 240, escalation_at_percent: 70 },
  high:     { first_response_mins: 60, resolution_mins: 480, escalation_at_percent: 75 },
  medium:   { first_response_mins: 240, resolution_mins: 1440, escalation_at_percent: 80 },
  low:      { first_response_mins: 480, resolution_mins: 4320, escalation_at_percent: 85 }
};

const ESCALATION_CONTACTS = {
  critical: { slack_user: '@oncall-lead', email: 'oncall@REPLACE_YOUR_DOMAIN.com' },
  high:     { slack_user: '@support-lead', email: 'support-lead@REPLACE_YOUR_DOMAIN.com' },
  medium:   { slack_user: '@support-manager', email: 'support-manager@REPLACE_YOUR_DOMAIN.com' },
  low:      { slack_user: '@support-team', email: 'support@REPLACE_YOUR_DOMAIN.com' }
};

return [{ json: { sla_policy: SLA_POLICY, escalation_contacts: ESCALATION_CONTACTS, check_time: new Date().toISOString() } }];

const tickets = Array.isArray($input.item.json) ? $input.item.json : [$input.item.json];
const slaPolicy = {
  critical: { first_response_mins: 15, resolution_mins: 240, escalation_at_percent: 70 },
  high:     { first_response_mins: 60, resolution_mins: 480, escalation_at_percent: 75 },
  medium:   { first_response_mins: 240, resolution_mins: 1440, escalation_at_percent: 80 },
  low:      { first_response_mins: 480, resolution_mins: 4320, escalation_at_percent: 85 }
};

const priorityMap = { 1: 'low', 2: 'medium', 3: 'high', 4: 'critical' };
const now = Date.now();

const analyzed = tickets.map(ticket => {
  const priority = priorityMap[ticket.priority] ?? 'medium';
  const policy = slaPolicy[priority];

  const createdAt = new Date(ticket.created_at).getTime();
  const ageMinutes = (now - createdAt) / 60000;

  // SLA deadline = created_at + resolution_mins
  const slaDeadline = new Date(createdAt + policy.resolution_mins * 60000);
  const minutesToBreach = (slaDeadline.getTime() - now) / 60000;
  const percentElapsed = Math.round((ageMinutes / policy.resolution_mins) * 100);

  const hasFirstResponse = !!ticket.stats?.first_responded_at;
  const firstResponseAge = hasFirstResponse 
    ? (new Date(ticket.stats.first_responded_at).getTime() - createdAt) / 60000 
    : ageMinutes;
  const firstResponseBreached = !hasFirstResponse && ageMinutes > policy.first_response_mins;

  let risk_level;
  if (minutesToBreach < 0) risk_level = 'breached';
  else if (percentElapsed >= policy.escalation_at_percent) risk_level = 'critical_risk';
  else if (percentElapsed >= 50) risk_level = 'at_risk';
  else risk_level = 'on_track';

  const needsEscalation = risk_level === 'breached' || risk_level === 'critical_risk';

  return {
    ticket_id: ticket.id,
    subject: ticket.subject,
    requester_id: ticket.requester_id,
    assignee_id: ticket.responder_id,
    priority,
    status: ticket.status,
    age_minutes: Math.round(ageMinutes),
    minutes_to_breach: Math.round(minutesToBreach),
    percent_elapsed: percentElapsed,
    sla_deadline: slaDeadline.toISOString(),
    risk_level,
    needs_escalation: needsEscalation,
    first_response_breached: firstResponseBreached,
    has_first_response: hasFirstResponse,
    created_at: ticket.created_at,
    tags: ticket.tags ?? []
  };
});

// Sort by risk (breached first, then by minutes_to_breach ascending)
analyzed.sort((a, b) => {
  const riskOrder = { breached: 0, critical_risk: 1, at_risk: 2, on_track: 3 };
  const rDiff = riskOrder[a.risk_level] - riskOrder[b.risk_level];
  if (rDiff !== 0) return rDiff;
  return a.minutes_to_breach - b.minutes_to_breach;
});

const needsAction = analyzed.filter(t => t.needs_escalation);

return needsAction.map(t => ({ json: t }));

