const raw = $input.item.json.message?.content ?? '{}';
let aiPlan;
try { aiPlan = JSON.parse(raw); }
catch { aiPlan = { escalation_message: 'Ticket requires immediate attention.', immediate_actions: ['Review ticket', 'Contact requester', 'Escalate to senior agent'], resolution_estimate_mins: 60, escalation_reason: 'SLA breach imminent' }; }

return {
  ...($input.item.json),
  ai_escalation_message: aiPlan.escalation_message,
  ai_immediate_actions: aiPlan.immediate_actions,
  ai_resolution_estimate_mins: aiPlan.resolution_estimate_mins,
  ai_escalation_reason: aiPlan.escalation_reason,
  status_emoji: $input.item.json.risk_level === 'breached' ? ':red_circle:' : ':large_orange_circle:'
};

